import { DASHBOARD_DATA, HOME_STEPS_DATA } from './keys'
const initialState = {
     homestepdata: {
        title_for_layout:'Wall Dashboard',
        feedCreated:null,
        isEmbed:null,
        isFeedCustomised:null,
        productCreated:null,
        processAttempted:null,
        title:null,
        noSidebar:null,
        lastWidge:{
           wall:{
              id:null,
              name:null,
              url:null,
              status:null,
           }
        }
     }
     }
export default function reducer(state = initialState, action) {
    switch (action.type) {
        case HOME_STEPS_DATA: {
            return { ...state, homestepdata: action.payload }
        }
        default:
            return { ...state }
    }
}