import { CREATE_FEED_DATA, DISCONNECT_ACC, FETCH_ACCOUNTS, FETCH_ACCOUNT_API_STATUS, FETCH_PERSONAL_ACCOUNT, SET_ACCOUNT_FEED, SET_AUTH_OBJ, FETCH_GOOGLE_ACCOUNTS, SNAPUP_DETAIL, ADD_FEED_NETWORKS, NETWORK_TAB_DETAILS, SET_CHILD_ACCOUNT_FEED, SET_FEED_OBJ_STATE, SET_AUTOCOMPLETE_HANDLE, SET_AUTOCOMPLETE_LIST_STATE, SET_AUTOCOMPLETE_HANDLE_STATE, SET_SELECTED_HANDLE_STATE, SET_SELECTED_LIST_STATE, SET_FEED_LOADING_STATE, SET_ERROR_MESSAGE_STATE, SET_ERROR_SHOW_STATE, SET_SNAP_UP_LOADER } from "./keys"

const initialState = { connectedAcc: null, createFeed: null, selectedAccount: null, selectedChildAccount: null, authObj: {}, personalAccount: null, accountStatus: false, googleReviewFeedData: [], details: {}, addFeedNetworks: null, networkDetails: { networkTab: null, loading: false }, feedObj: {}, autoCompleteHandle: [], autoCompleteList: [], selectedHandle: {}, selectedList: {}, createFeedLoading: false, error: { show: false, message: "" }, snapUpLoad: true }

export default function reducer(state = initialState, action) {
    switch (action.type) {
        case FETCH_ACCOUNTS: {
            return { ...state, connectedAcc: action.payload }
        }

        case FETCH_PERSONAL_ACCOUNT: {
            return { ...state, personalAccount: action.payload }
        }

        case FETCH_ACCOUNT_API_STATUS: {
            return { ...state, accountStatus: action.payload }
        }

        case DISCONNECT_ACC: {
            var cAcc = state.connectedAcc
            cAcc = cAcc.filter(acc => acc.ConnectedAccounts.id != action.payload)
            if (cAcc.length == 0) cAcc = []
            return { ...state, connectedAcc: cAcc }
        }

        case CREATE_FEED_DATA: {
            return { ...state, createFeed: action.payload }
        }

        case SET_ACCOUNT_FEED: {
            return { ...state, selectedAccount: action.payload }
        }
        case SET_CHILD_ACCOUNT_FEED: {
            return { ...state, selectedChildAccount: action.payload }
        }
        case SET_AUTH_OBJ: {
            return { ...state, authObj: action.payload }
        }
        case FETCH_GOOGLE_ACCOUNTS: {
            return { ...state, googleReviewFeedData: action.payload }
        }
        case SNAPUP_DETAIL: {
            return { ...state, details: action.payload }
        }

        case ADD_FEED_NETWORKS: {
            return { ...state, addFeedNetworks: action.payload }
        }

        case NETWORK_TAB_DETAILS: {
            return { ...state, networkDetails: { ...action.payload, loading: false } }
        }

        case SET_FEED_OBJ_STATE: {
            return { ...state, feedObj: { ...state.feedObj, ...action.payload }, error: resetErrorState() }
        }

        case SET_AUTOCOMPLETE_LIST_STATE: {
            return { ...state, autoCompleteList: action.payload }
        }
        case SET_AUTOCOMPLETE_HANDLE_STATE: {
            return { ...state, autoCompleteHandle: action.payload }
        }
        case SET_SELECTED_HANDLE_STATE: {
            return { ...state, selectedHandle: action.payload }
        }
        case SET_SELECTED_LIST_STATE: {
            return { ...state, selectedList: action.payload }
        }

        case SET_FEED_LOADING_STATE: {
            return { ...state, createFeedLoading: action.payload }
        }

        case SET_ERROR_MESSAGE_STATE:
            return { ...state, error: action.payload }

        case SET_ERROR_SHOW_STATE:
            return { ...state, error: { ...state.error, show: action.payload } }

        case SET_SNAP_UP_LOADER:
            return {...state, snapUpLoad: action.payload}

        default:
            return { ...state }
    }

}


const resetErrorState = () => { return { show: false, message: "" } }