import { MODERATION_GET_CTA, MODERATION_UPDATE_CTA } from './keys'
const initialState = { data: null }

export default function reducer(state = initialState, action) {
    switch (action.type) {
        case MODERATION_GET_CTA: {
            return { ...state, data: action.payload }
        }
        case MODERATION_UPDATE_CTA: {
            return { ...state, data: action.payload }
        }
        default:
            return { ...state }
    }

}