import { TOGGLE_APPSMORE_SECTION, TOGGLE_PLAN_SECTION, TOGGLE_ADD_FEEDS_SECTION, TOGGLE_MANAGE_FEEDS_SECTION, TOGGLE_CUSTOMIZATION_SECTION, TOGGLE_THEMES_SECTION, TOGGLE_PUBLISH_SECTION, REFRESH_THEMES_SECTION, TOGGLE_CTA_SECTION, TOGGLE_PRICE_SECTION } from "./keys";

const reset = {
    showPricing: false,
    showAppsMore: false,
    showAddFeed: false,
    showManageFeed: false,
    showThemes: false,
    showCustomization: false,
    showPublish: false,
    showCta: false,
    showPrice: false,
    priceP_id:2,
}
const initialState = {
    ...reset,
    
}

export default function reducer(state = initialState, action) {
    const { type, payload } = action;

    switch (type) {

        case TOGGLE_PLAN_SECTION: {
            return {
                ...reset, showPricing: payload
            }
        }

        case TOGGLE_APPSMORE_SECTION: {
            return {
                ...reset, showAppsMore: payload
            }
        }

        case TOGGLE_ADD_FEEDS_SECTION: {
            return {
                ...reset, showAddFeed: payload,

            }
        }

        case TOGGLE_MANAGE_FEEDS_SECTION: {
            return {
                ...reset, showManageFeed: payload,

            }
        }

        case TOGGLE_THEMES_SECTION: {
            return {
                ...reset, showThemes: payload,
            }
        }

        case TOGGLE_CUSTOMIZATION_SECTION: {
            return {
                ...reset,
                showCustomization: payload
            }
        }
        case TOGGLE_PUBLISH_SECTION: {
            return {
                ...reset,
                showPublish: payload
            }
        }
        case TOGGLE_CTA_SECTION: {
            return {
                ...reset,
                showCta: payload
            }
        }

        case TOGGLE_PRICE_SECTION: { 
            return {
                ...reset,
                showPrice: payload.toggleValue,
                priceP_id: payload.id 
            }
        }

        default:
            return { ...state }
    }
}