import { PRODUCT_SUBSCRIPTION_DATA , SOCIAL_ACCOUNT_DATA, DELETE_SOCIAL_ACCOUNT_DATA, ADD_ACCOUNT_DATA, ACCOUNT_CARD_DATA, ACCOUNTS_LOADER_STATE} from './keys'

const initialState ={accountInfo :null, productSubscriptions:null,socialAccounts:null , addAccount:null, accountCardData:null, accountsLoading: false }

export default function reducer(state= initialState, action ){

    switch(action.type)
    {

            case PRODUCT_SUBSCRIPTION_DATA:{
                return {...state, productSubscriptions:action.payload}
            }


            case SOCIAL_ACCOUNT_DATA:{
                return {...state, socialAccounts:action.payload}
            }

            case ADD_ACCOUNT_DATA:{
                return {...state, addAccount:action.payload}
            }

            case ACCOUNT_CARD_DATA:{
                return {...state, accountCardData:action.payload}
            }

            case ACCOUNTS_LOADER_STATE:{
                return { ...state, accountsLoading : action.payload}
            }

            
            case DELETE_SOCIAL_ACCOUNT_DATA:{
                let newdata = state.socialAccounts;
                newdata.accountInformations = state.socialAccounts.accountInformations.filter((item)=>{ return item.ConnectedAccounts.id !=action.payload.feedId })
                return {...state, socialAccounts:newdata, accountsLoading: false}
            }
            
            default:
                return { ...state }
    }
}