export const validatePassword = (password) => {
    let strength = 0;
    var caseMatch = [];

    if (password.match(/([a-z].*[A-Z])|([A-Z].*[a-z])/)) {
        strength += 1;
        caseMatch.push('1');
    } else {
        caseMatch = caseMatch.filter(item => item !== '1');
    }

    if (password.match(/([0-9])/)) {
        strength += 1;
        caseMatch.push('2');
    } else {
        caseMatch = caseMatch.filter(item => item !== '2');
    }

    if (password.match(/([!,%,&,@,#,$,^,*,?,_,~])/)) {
        strength += 1;
        caseMatch.push('3');
    } else {
        caseMatch = caseMatch.filter(item => item !== '3');
    }

    if (password.length > 7) {
        strength += 1;
        caseMatch.push('4');
    } else {
        caseMatch = caseMatch.filter(item => item !== '4');
    }

    return { strength, caseMatch };
};

export function setCookie(name, value) {
    var expires = "";
    var date = new Date();
    date.setTime(date.getTime() + 30 * 24 * 60 * 60 * 1000);
    expires = "; expires=" + date.toUTCString();
    document.cookie = name + "=" + (value || "") + expires + "; path=/";
}

