export const toAbsoluteUrl = pathname => `https://cloud.tagshop.ai/frontend/analytics` + pathname;

export const reArrangeSeries = (data) => {
    const newSeries = [];
    const newDate = [];
    const unixDate = [];
    const { series, labels, currency } = data;
    if (series) {
        for (let i = 0; i < series.length; i++) {
            const seriesItem = series[i];
            const newData = [];

            for (let j = 0; j < labels.length; j++) {

                const [day, month, year] = labels[j].split('/').map(Number);

                const dateObj = new Date(year, month - 1, day + 1);
                const unixTimestamp = dateObj.getTime();
                newData.push([unixTimestamp, seriesItem.data[j]]);
                unixDate.push(unixTimestamp);
            }
            newSeries.push({ name: seriesItem.name, data: newData });
        }
    }

    if (labels) {
        labels.forEach(dateStr => {
            newDate.push(moment(dateStr, "DD/MM/YYYY").format("DD MMM YYYY"));
        });
    }

    return { newSeries, newDate, unixDate, currency };
}

