export const CHANGE_WEBSITE_WALL = (wallId, limit, themeId, callBack) => {
    const { wall } = store.getState().appData
    const { websiteList } = store.getState().websiteList
    return (dispatch) => {
        dispatch({ type: ISPOST_LOADING, payload: true })
        dispatch({ type: LIVE_PREVIEW_LOADER, payload: true }); 
        const webId = localStorage.getItem('website_id') ? localStorage.getItem('website_id') : websiteList.length > 0 ? websiteList[0].wall.Wall.id : ''
        if (wallId) {
            new HttpClient().get(`${GET_WALL_POST_DATA}/${wallId ? wallId : 0}/${webId}/${themeId ? themeId : 0}/${limit}`).then((response) => {
                const { postData, error_code, response_code, customPost, after, older_days, older_post, UgcSettings } = response.data;

                if (response_code == 200) {
                    dispatch({ type: NEW_WALL_DATA, payload: { postData, onsite_status: UgcSettings?.onsite_status, error_code, after, customPost, older_days, older_post, wallId: wallId } })
                }
                setTimeout(() => {
                    dispatch({ type: LIVE_PREVIEW_LOADER, payload: false });
                    dispatch({ type: ISPOST_LOADING, payload: false })
                    if (callBack) callBack()
                }, 500);
                // setTimeout(() => {
                //     dispatch({ type: CHANGE_THEME_ID, payload: wall?.Personalization?.commerceTheme ? wall?.Personalization?.commerceTheme : 16 }) 
                //  }, 500);
            }).catch((error) => {
                dispatch({ type: ISPOST_LOADING, payload: false })
                dispatch({ type: LIVE_PREVIEW_LOADER, payload: false });
                if (callBack) callBack()
            });
        }
        else {
            const postData = []
            dispatch({ type: NEW_WALL_DATA, payload: { postData, onsite_status: wall?.UgcSettings?.onsite_status } })
            dispatch({ type: LIVE_PREVIEW_LOADER, payload: false });
            dispatch({ type: ISPOST_LOADING, payload: false })
            if (callBack) callBack()
        }

    };
}




export const CHANGE_WEBSITE = (data) => {
    return (dispatch) => {
        dispatch({ type: GET_APP_DATA, payload: data, heightEvent: null });
        dispatch({ type: LIVE_PREVIEW_LOADER, payload: true });
        setTimeout(() => {
            dispatch({ type: CHANGE_THEME_ID, payload: data?.wall?.Personalization?.commerceTheme ? data?.wall?.Personalization?.commerceTheme : 61 })
            dispatch({ type: SET_ALL_UPDATED, payload: false })
        }, 1000);
        setTimeout(() => {
            dispatch({ type: LIVE_PREVIEW_LOADER, payload: false });
        }, 1000);
    };
}