export const GET_POST_COUNT = (feedId, networkId, navigate) => {
    const obj = {
        wallId: localStorage.getItem('wallId'),
        feedId,
        networkId: networkId
    }
    const toastId = TOAST_LOADING()
    new HttpClient().post(GET_COUNT, obj, { validateStatus: false }).then(res => {
        const { responseCode, resposneMessage, postCount } = res.data
        if (responseCode == 200) {
            store.dispatch(TAGSHOP_USER_HOME_DATA())
            store.dispatch(GET_FEEDS())
            TOAST_UPDATE(toastId, "success", `${postCount} ${postCount > 1 ? 'posts' : 'post'} added successfully`)
            setTimeout(() => {
                navigate(`/content/moderation/${localStorage.getItem('wallId') ? localStorage.getItem('wallId') : ''}`)
            }, 1500);
        }
        else TOAST_UPDATE(toastId, "error", resposneMessage.message ? resposneMessage.message : resposneMessage)
        store.dispatch(SET_FEED_LOADING(false))

    }).catch(error => {
        TOAST_UPDATE(toastId, "error", "Some Error Occured!!")
        store.dispatch(SET_FEED_LOADING(false))
    })
}

const uploadUrlToQr = (url, id) => {
    QRCode.toDataURL(url)
        .then(url => {
            var myFile = dataURItoBlob(url);
            var newFileName = `onsiteupload/images/${id}.png`
            const params = {
                ACL: 'public-read',
                Body: myFile,
                Bucket: S3_BUCKET,
                ContentType: 'image/png',
                ContentEncoding: 'base64',
                Key: newFileName
            };
            myBucket.upload(params)
                .on('httpUploadProgress', (evt) => {
                    if (Math.round((evt.loaded / evt.total) * 100) == 100) {

                    }

                })
                .send((err) => {

                })
        })
        .catch(err => {
            console.error(err)
        })
}

export const CREATE_ONSITE_FEED = (obj, closeModal, uploadQr = false, url = "", navigate) => {
    new HttpClient().post(ONSITE_FEED, obj, { validateStatus: false }).then(res => {
        const { responseCode, responseData, responseStatus, value1, responseMessage } = res.data
        store.dispatch(GET_FEEDS())
        if (parseInt(responseCode) == 200) {
            if (uploadQr && url && value1) {
                uploadUrlToQr(url, value1)
            }
            TOAST_SUCCESS(responseData)
            store.dispatch(GET_ALL_WEBSITE_LIST())
            store.dispatch(SNAPUP_DETAILS_ACTION())
        }
        else {
            TOAST_ERROR(responseMessage ? responseMessage : responseData)
        }
        if (responseStatus == "Upgrade") {
            closeModal()
            setTimeout(() => {
                navigate('/price')
            }, 1500);
        }
        if (responseStatus != "Upgrade") {
            
            closeModal()
        }
        else {
            if (responseStatus != "Upgrade") {
                setTimeout(() => {
                    closeModal()
                }, 1000);
            }
        }
    }).catch(ex=>{
        const { data } = ex.response
        closeModal()
        TOAST_ERROR(data.responseMessage ? data.responseMessage : 'Something went wrong, please try again later.')
    })
}

export const SNAPUP_DETAILS_ACTION = () => {
    return (dispatch) => {
        dispatch({ type: SET_SNAP_UP_LOADER, payload: true});
        new HttpClient()
            .get(`${feedOnsite}/${localStorage.getItem('wallId')}`)
            .then((detailReponse) => {
                const { responseCode, responsedata } = detailReponse.data
                if (responseCode == 200) {
                    dispatch({ type: SNAPUP_DETAIL, payload: responsedata?.feed});
                    dispatch({ type: SET_SNAP_UP_LOADER, payload: false});
                }
            });
    };
}


