export const CREATE_FEED_ACTION = (networkId, navigate) => (dispatch, getState) => {
    const { feedObj, selectedAccount, selectedChildAccount, networkDetails, selectedHandle, selectedList } = getState().addFeedReducer
    var payload;
    const toastId = TOAST_LOADING()
    dispatch(SET_FEED_LOADING(true))


    switch (parseInt(networkId)) {

        //* Instagram Buissness/ personal
        case 18:
            var obj = {
                wallId: localStorage.getItem("wallId"),
                networkId: 18,
                moderation: Number(feedObj.moderation) || 0,
                account: 0,
                feedText: feedObj.feedText,
                hashtagCaption: Number(feedObj.hashtagCaption) || 0,
                filter: parseInt(feedObj.filter),
                hashtagIGTV: Number(feedObj.hashtagIGTV) || 0,
                onlyReels: Number(feedObj.onlyReels) || 0
            }
            if ([34, 24, 25, 66].includes(parseInt(feedObj.filter))) {
                obj['feedText'] = selectedChildAccount?.ConnectedAccounts?.value2 || null
                obj['accountId'] = selectedChildAccount?.ConnectedAccounts?.id || null
            }
            else if (feedObj.filter == 1) {
                obj['accountId'] = selectedChildAccount?.ConnectedAccounts?.id || null
                obj['networkId'] = 2
            }
            else obj['accountId'] = selectedAccount?.ConnectedAccounts?.id || null
            payload = obj
            break;

        //* tiktok
        case 28:
            var obj = {
                wallId: localStorage.getItem("wallId"),
                networkId: 28,
                moderation: Number(feedObj.moderation) || 0,
                account: null,
                filter: parseInt(feedObj.filter),
            }
            if (feedObj.filter == 70) obj['tiktok_post_url'] = feedObj.feedText
            else obj['feedText'] = feedObj.feedText
            payload = obj
            break;

        //* Twitter
        case 1:
            var obj = {
                wallId: localStorage.getItem("wallId"),
                networkId: 1,
                username: "",
                moderation: Number(feedObj.moderation) || 0,
                excludeRetweet: Number(feedObj.excludeRetweet) || 0,
                excludeReplies: Number(feedObj.excludeReplies) || 0,
                feedText: feedObj.feedText,
                // authRequire: networkDetails.authRequire || 0,
                connetedAccount: 0,
                accountId: selectedAccount?.ConnectedAccounts?.id || 0,
                listname: "",
                multiplePhoto: Number(feedObj.multiplePhoto) || 0,
                filter: parseInt(feedObj.filter)
            }
            if (feedObj.filter == 3) {
                obj['userId'] = selectedHandle.id || "";
                obj['listname'] = selectedList.name || "";
                obj['listId'] = selectedList.id || "";
            }
            payload = obj
            break

        //* Facebook
        case 3:
            var obj = {
                wallId: localStorage.getItem("wallId"),
                networkId: 3,
                moderation: Number(feedObj.moderation) || 0,
                connetedAccount: 0,
                feedType: parseInt(feedObj.filter),
                account: selectedAccount?.ConnectedAccounts.id || null,
                field: feedObj.feedText,
                filter: parseInt(feedObj.filter),
                hashtagIGTV: 0,
                onlyReels: 0
            }

            if (feedObj.filter == 1) obj['field'] = ""

            if (feedObj.filter == 55 || feedObj.filter == 62) {
                obj['account'] = selectedChildAccount?.ConnectedAccounts.id || null;
                obj['connetedAccount'] = selectedChildAccount?.ConnectedAccounts.parent || null;
            }
            payload = obj
            break;

        //* Google
        case 4:
            var obj = {
                wallId: localStorage.getItem("wallId"),
                networkId: 4,
                filter: parseInt(feedObj.filter),
                field33: feedObj.feed33,
                field33placeId: feedObj.field33placeId,
                field33placeName: feedObj.field33placeName,
                connetedAccount: 0,
                account: 0,
                hashtagIGTV: 0,
                onlyReels: 0,
                moderation: Number(feedObj.moderation) || 0
            }
            if (feedObj.filter == 29) {
                obj['field33'] = ""
                obj['field33placeId'] = ""
                obj['field33placeName'] = ""
                obj['feedType'] = 2
                obj['account'] = selectedChildAccount?.ConnectedAccounts.id || null
                obj['connetedAccount'] = selectedAccount?.ConnectedAccounts.id || null
            }
            payload = obj
            break;

        //* Pinterest
        case 5:
            var obj = {
                wallId: localStorage.getItem("wallId"),
                networkId: 5,
                moderation: Number(feedObj.moderation) || 0,
                connetedAccount: 0,
                feedType: parseInt(feedObj.filter),
                account: 0,
                filter: parseInt(feedObj.filter),
            }
            if (feedObj.filter == 1) obj['field1'] = feedObj.feedText
            if (feedObj.filter == 12) {
                obj['field12boardurl'] = feedObj.feedText
                if (isValidUrl(feedObj.feedText)) {
                    var feedTxtURL = new URL(feedObj.feedText)
                    if (feedTxtURL?.origin && feedTxtURL?.pathname) {
                        obj['field1'] = String(feedTxtURL?.pathname)?.replace(/^\/|\/$/g, '');
                    }
                }
            }
            payload = obj
            break;

        //* YouTube
        case 7:
            var obj = {
                wallId: localStorage.getItem("wallId"),
                networkId: 7,
                filter: parseInt(feedObj.filter),
                moderation: Number(feedObj.moderation) || 0,
                feedText: feedObj.feedText,
                channelId: feedObj.channelId
            }
            if (feedObj.filter == 32) {
                obj['latlng'] = feedObj.latLng || ""
                obj['keywords'] = feedObj.keywords || ""
                obj['channelId'] = ""
            }
            payload = obj
            break;

        //* Flicker 
        case 6:
            var obj = {
                wallId: localStorage.getItem("wallId"),
                networkId: 6,
                moderation: Number(feedObj.moderation) || 0,
                connetedAccount: 0,
                feedType: parseInt(feedObj.filter),
                account: 0,
                filter: parseInt(feedObj.filter),
                hashtagIGTV: 0,
                onlyReels: 0,
                [`field${feedObj.filter}`]: feedObj.feedText
            }
            payload = obj
            break;

        //* Vimeo
        case 8:
            var obj = {
                wallId: localStorage.getItem("wallId"),
                networkId: 8,
                filter: parseInt(feedObj.filter),
                moderation: Number(feedObj.moderation) || 0,
                feedText: feedObj.feedText,
                accountId: selectedAccount?.ConnectedAccounts?.id || null,
            }
            payload = obj;
            break;

        //* Airbnb
        case 23:
            var obj = {
                wallId: localStorage.getItem("wallId"),
                networkId: 23,
                moderation: Number(feedObj.moderation) || 0,
                connetedAccount: 0,
                feedType: parseInt(feedObj.filter),
                airbnb_page_review: feedObj.feedText,
                account: 0,
                filter: parseInt(feedObj.filter),
                hashtagIGTV: 0,
                onlyReels: 0
            }
            payload = obj
            break


        default:
            break;
    }

    CREATE_FEED_API(payload).then(res => {
        const { responseCode, resposneMessage, response, postCount, response_code, responseData } = res.data;
        if (responseCode == 200 || response_code == 200) {
            TOAST_UPDATE(toastId, "success", resposneMessage)

            GET_POST_COUNT(responseData, payload.networkId, navigate)
        }
        else {
            TOAST_UPDATE(toastId, "error", resposneMessage?.message || resposneMessage)
            dispatch(SET_FEED_LOADING(false))
        }


    }).catch(err => {
        const { responseMessage } = err.response.data
        TOAST_UPDATE(toastId, "error", responseMessage || "Some Error Occured!!")
        dispatch(SET_FEED_LOADING(false))
    })
}

