export const TAGSHOP_USER_HOME_DATA = () => {
    return (dispatch) => {
        new HttpClient()
            .get(`${HOME_DASHBOARD_URL}`)
            .then((response) => {
                const { responseData, responseCode } = response.data;
                if (responseCode == 200) {
                    localStorage.setItem("analytics_wall", '0')
                    dispatch({ type: DASHBOARD_DATA, payload: responseData, });
                    if (!(localStorage.getItem("wallId") && JSON.parse(localStorage.getItem("wallId")))){
                        localStorage.setItem('wallId', responseData.allWalls.length > 0 ? responseData.allWalls[0].id : '')
                    }
                }
            })
            .catch((error) => {
                console.log("ERROR", error)
            });
    };
};

