export const ACCOUNTS_LOADER = (state) => { return (dispatch) => dispatch({ type: ACCOUNTS_LOADER_STATE, payload: state }) }

export const TAGGSHOP_SOCIAL_ACCOUNT_DATA = (id = null, callBack) => {
    return (dispatch) => {
        dispatch(ACCOUNTS_LOADER(true))
        const userData = store.getState().authorized?.userData?.user_data
        new HttpClient()
            .get(`${GET_SOCIAL_ACCOUNT_URL}`)
            .then((response) => {
                const { responseData, responseCode } = response.data;
                if (responseCode == 200) {
                    dispatch({
                        type: SOCIAL_ACCOUNT_DATA,
                        payload: responseData,
                    });
                }
                dispatch(ACCOUNTS_LOADER(false))

                if (callBack) callBack(false)
            })
            .catch((error) => {
                if (callBack) callBack(false)
                console.log("ERROR", error)
                dispatch(ACCOUNTS_LOADER(false))
            });
    }
}


const setActiveWall = (formData, responseData) => {
    const allWalls = store.getState()?.dashboardData?.dashboarddata?.allWalls;
    let newWallId = '';

    if (formData?.action === 1) {
        localStorage.setItem("wallId", responseData?.id);
        newWallId = responseData?.id;
    }

    if (formData?.action === 3) {
        const remainingWalls = allWalls.filter(item => item.id != formData?.id);
        newWallId = localStorage.getItem('wallId') != String(formData.id) ? localStorage.getItem('wallId') : remainingWalls.length ? remainingWalls[0].id : '';
        localStorage.setItem("wallId", newWallId);
    }

    if (formData?.action === 2) {
        newWallId = localStorage.getItem('wallId');
    }

    return newWallId;
};


export const GALLERY_WALL_UPDATE = (formData, navigate, callBack) => {
    return async (dispatch) => {
        dispatch(ACCOUNTS_LOADER(true));
        try {
            const oldId = localStorage.getItem('wallId')
            const { data: { responseCode, responseData, responseMessage } } = await new HttpClient().post(`${SHOPPABLE_GALLERY_URL}/addUpdate`, formData);
            
            if (responseCode === 200) {
                const wallId = setActiveWall(formData, responseData);
                    dispatch({ type: GALLERY_DATA_UPDATE, payload: { responseData, formData } });
                    dispatch(getModeration());
                    if(oldId != wallId && formData?.action == 3) dispatch(GET_FEEDS())
                    if(formData?.action == 3){
                        dispatch(GET_ALL_WEBSITE_LIST())
                        dispatch(GET_ALL_SHOPON_LIST())
                        dispatch(GET_ALL_EMAIL_LIST())
                    }
                    dispatch({ type: MODERATION_RESET, payload: true });
                if (wallId) {
                    TOAST_SUCCESS(responseMessage);

                        const redirectPath = formData?.action === 1
                            ? `/content/addfeed/${wallId}`
                            : window.location.pathname.includes('/content/moderation')
                                ? `/content/moderation/${wallId}`
                                : `/content/managefeed/${wallId}`;
                     
                    navigate(redirectPath)
                }
                else{
                    navigate(`/content/moderation/`)
                }
                callBack();
            } else if (responseCode === 201) {
                upgradePopUpShow(navigate);
                callBack();
            }
        } catch (error) {
            const errorMessage = error?.response?.data?.responseMessage || "An unexpected error occurred!";
            TOAST_ERROR(errorMessage);
        } finally {
            dispatch(ACCOUNTS_LOADER(false));
        }
    };
};


const upgradePopUpShow = (navigate) => {
    Swal.fire({
        title: `Upgrade to Add More Galleries`,
        text: `Oops! Looks like you need to upgrade your plan in order to add more Galleries`,
        icon: 'error',
        showCancelButton: true,
        cancelButtonText: "Cancel",
        confirmButtonText: "Upgrade Now!",

    }).then((result) => {
        if (result.value) {
            navigate('/price')
        }
        else if (result.dismiss === "cancel") { }
    });
}

