export const GET_DASHBOARD_DATA = (start, end) => {
    let startDate = moment(start, "DD-MM-YYYY").startOf('day').format("YYYY-MM-DD HH:mm:ss");
    let endDate = moment(end, "DD-MM-YYYY").endOf('day').format("YYYY-MM-DD HH:mm:ss");
    return (dispatch) => {
        DASHBOARD_BUSINESS_OVERVIEW(dispatch, startDate, endDate)
        DASHBOARD_UGC_ANALYTICS(dispatch, startDate, endDate)
        DASHBOARD_TOP_CREATOR(dispatch, startDate, endDate)
        DASHBOARD_TOP_PERFORMING_POST_ANALYTICS(dispatch, startDate, endDate)
        DASHBOARD_TOP_PERFORMING_PRODUCT_ANALYTICS(dispatch, startDate, endDate)
        store.dispatch(DASHBOARD_GALLERY_ANALYTICS(localStorage.getItem('wallId'), startDate, endDate))
        store.dispatch(DASHBOARD_WEBSITE_ANALYTICS(localStorage.getItem('website_id'), startDate, endDate))
        store.dispatch(DASHBOARD_SHOPON_ANALYTICS(localStorage.getItem('shopOn_id'), startDate, endDate))
        DASHBOARD_CONNECTED_ACCOUNT(dispatch)
    }
}


