export const getFbAuthToken = (c, callBack, setCode) => {
    axios.get(`https://graph.facebook.com/v15.0/oauth/access_token?client_id=${'117029975354072'}&redirect_uri=${`${BASE_URL}/feeds/authCallback/`}&client_secret=${"0cd429359e4892f79065f9810d5c906c"}&code=${c}`).then(res => {
        const { data } = res
        if (data) {
            const accObj = {
                token: data.access_token || "",
                networkId: parseInt(localStorage.getItem('networkId')),
                validity: data.expires_in || 34656,
                reconnectAccount: 0,
                wallId: localStorage.getItem('wallId')

            }
            store.dispatch(ACTION_ADD_AUTH_OBJ(accObj))
            setCode(false)
        }
    }).catch(error => { })
}


export const getVimeoAuth = (c, callBack, setCode) => {
    const feed_obj = JSON.parse(localStorage.getItem("createFeedObj"))

    const accObj = {
        token: "w",
        networkId: 8,
        code: c,
        reconnectAccount: 0,
        wallId: localStorage.getItem('wallId'),
        // is_v2: 1
    }

    ADD_FEED_ACCOUNT(accObj).then(res => {
        const { responseCode, resposneMessage, responseData } = res.data
        if (responseCode == 200) {
            TOAST_SUCCESS(resposneMessage)
            store.dispatch(TAGSHOP_USER_HOME_DATA())
            CREATE_FEED({ ...feed_obj, accountId: responseData.id ? responseData.id : "" }, callBack, false)
        }
        else {
            TOAST_ERROR(resposneMessage)
            setTimeout(() => {
                window.location = `${HOST_URL}content/moderation/${localStorage.getItem('wallId')}`
            }, 1000);
        }
    })

}


