


export const permissionDenied = (user_data, navigateRoute) => {
    const { collaborator } = user_data
    if (collaborator && Object.keys(collaborator).length > 0 && collaborator.activeAccount != 0) {
        const { activeAccount, permissions, workplaces } = collaborator
        const currentCollaborator = workplaces.filter(workplace => (workplace.owner == activeAccount || workplace.parent == activeAccount))
        if (currentCollaborator?.length > 0 && currentCollaborator[0].role == 2) {
            const { contentGallery, networkManager, otherSettings, product_catalog, publish } = permissions

            //product_catalog
            if (product_catalog == 0 && window.location.href.includes("content/products") && !window.location.href.includes("permission-denied")) navigateRoute('/permission-denied')

            //publish
            if (publish?.website == 0 && window.location.href.includes("website/publish") && !window.location.href.includes("permission-denied")) navigateRoute('/permission-denied')
            if (publish?.shopon == 0 && window.location.href.includes("shopon-bio/preview") && !window.location.href.includes("permission-denied")) navigateRoute('/permission-denied')
            if (publish?.email_camp == 0 && window.location.href.includes("email-campaign/publish") && !window.location.href.includes("permission-denied")) navigateRoute('/permission-denied')

            //otherSettings
            if (otherSettings?.analytics == 0 && window.location.href.includes("/analytics") && !window.location.href.includes("permission-denied")) navigateRoute('/permission-denied')
            if (otherSettings?.apps_more == 0 && window.location.href.includes("/more-apps") && !window.location.href.includes("permission-denied")) navigateRoute('/permission-denied')


            //networkManager
            if (networkManager?.manageFeed == 0 && (window.location.href.includes("/content/managefeed") || window.location.href.includes("/content/addfeed")) && !window.location.href.includes("permission-denied")) navigateRoute('/permission-denied')
            if (networkManager?.manageFeed == 1 && (window.location.href.includes("/content/addfeed") || window.location.href.includes("/content/reviewhub")) && !window.location.href.includes("permission-denied")) navigateRoute('/permission-denied')
            if (networkManager?.manageAccount == 0 && window.location.href.includes("/social-account") && !window.location.href.includes("permission-denied")) navigateRoute('/permission-denied')

            //other routes blocked
            if (window.location.href.includes("/transactions") && !window.location.href.includes("permission-denied")) navigateRoute('/permission-denied')
            if (window.location.href.includes("/collaborator") && !window.location.href.includes("/collaborator/request") && !window.location.href.includes("permission-denied")) navigateRoute('/permission-denied')
            if (window.location.href.includes("/price") && !window.location.href.includes("permission-denied")) navigateRoute('/permission-denied')

        }
        else if (currentCollaborator?.length > 0 && currentCollaborator[0].role == 1) {
            if (window.location.href.includes("/price") && !window.location.href.includes("permission-denied")) navigateRoute('/permission-denied')
            if (window.location.href.includes("/transactions") && !window.location.href.includes("permission-denied")) navigateRoute('/permission-denied')
        }
    }
    else if(!user_data.collaboratorAccess){
        if (window.location.href.includes("/collaborator") && !window.location.href.includes("/collaborator/request") && !window.location.href.includes("permission-denied")) navigateRoute('/permission-denied')
    }
    


}