import { CREATE_EMAIL_REDUCER, UPDATE_EMAIL_REDUCER,  DELETE_EMAIL_REDUCER, ALL_EMAIL_LIST_REDUCER, ACTIVE_EMAIL_REDUCER, LOADING_EMAIL_REDUCER , TOGGLE_ADD_EMAIL } from './keys'
const initialState = { 
    emailList: [],
    active_email:'',
    emailLoading:true,
    addEmailNow:false,
}
export default function reducer(state = initialState, action) {
    switch (action.type) {
        case ALL_EMAIL_LIST_REDUCER: {
            return { ...state, emailList: action.payload }
        }

        case CREATE_EMAIL_REDUCER: { 
            return { ...state, emailList: [...state.emailList, action.payload] };
          }
          
        case ACTIVE_EMAIL_REDUCER: { 
        return { ...state, active_email: action.payload };
        }

        case UPDATE_EMAIL_REDUCER:{
           const {id, responseData} = action.payload 
           let updatedWebsiteData = state.emailList.find((x) => x.id == id);
           updatedWebsiteData = responseData
        return { ...state,  emailList: state.emailList.map((x) =>  x.id == id ? updatedWebsiteData : x ) }; 
        }
        case DELETE_EMAIL_REDUCER:{ 
            const updatedWebsiteData = state.emailList.filter((x) => x.id != action.payload);  
         return { ...state,  emailList: updatedWebsiteData }; 
         }
         case LOADING_EMAIL_REDUCER:{ return { ...state,  emailLoading: action.payload }; } 
         case TOGGLE_ADD_EMAIL:{ return { ...state,  addEmailNow: action.payload }; } 
        
        default:
            return { ...state }
    }

}