import { DASHBOARD_BUSINESS_OVERVIEW_DATA, DASHBOARD_BUSINESS_OVERVIEW_LOADER, GALLERY_DATA_UPDATE, DASHBOARD_CONNECTED_ACCOUNT_DATA, DASHBOARD_CONNECTED_ACCOUNT_LOADER, DASHBOARD_CONTENT_GALLERY_DATA, DASHBOARD_CONTENT_GALLERY_LOADER, DASHBOARD_DATA, DASHBOARD_SHOPON_DATA, DASHBOARD_SHOPON_LOADER, DASHBOARD_TOP_CREATOR_DATA, DASHBOARD_TOP_CREATOR_LOADER, DASHBOARD_TOP_PERFORMING_POST_DATA, DASHBOARD_TOP_PERFORMING_POST_LOADER, DASHBOARD_TOP_PERFORMING_PRODUCT_DATA, DASHBOARD_TOP_PERFORMING_PRODUCT_LOADER, DASHBOARD_UGC_ANALYTICS_DATA, DASHBOARD_UGC_ANALYTICS_LOADER, DASHBOARD_WEBSITE_DATA, DASHBOARD_WEBSITE_LOADER, TOGGLE_ADD_GALLERY, UPDATE_DASHBOARD_DATA } from './keys'
import { caseStudy } from '../utils/Constent'
const initialState = { dashboarddata: null, wallsLoader: true, addGalleryNow: false, overview_loader: true, overview: null, accounts_loader: true, accounts: null, caseStudy, ugc: null, ugc_loader: true, top_creator: null, top_creator_loader: true, top_performing_post: null, top_performing_post_loader: true, top_performing_product: null, top_performing_product_loader: true, content_gallery_loader: true, content_gallery: null, website_loader: true, website: null, shopon_loader: true, shopon: null }

export default function reducer(state = initialState, action) {
    switch (action.type) {

        case DASHBOARD_DATA: { return { ...state, dashboarddata: action.payload, wallsLoader: false } }

        case UPDATE_DASHBOARD_DATA: { return { ...state, dashboarddata: { ...state.dashboarddata, allWalls: action.payload }, }; }
        case TOGGLE_ADD_GALLERY: { return { ...state, addGalleryNow: action.payload } }

        case DASHBOARD_BUSINESS_OVERVIEW_LOADER: { return { ...state, overview_loader: action.payload } }
        case DASHBOARD_BUSINESS_OVERVIEW_DATA: { return { ...state, overview: action.payload } }

        case DASHBOARD_CONNECTED_ACCOUNT_LOADER: { return { ...state, accounts_loader: action.payload } }
        case DASHBOARD_CONNECTED_ACCOUNT_DATA: { return { ...state, accounts: action.payload } }

        case DASHBOARD_UGC_ANALYTICS_LOADER: { return { ...state, ugc_loader: action.payload } }
        case DASHBOARD_UGC_ANALYTICS_DATA: { return { ...state, ugc: action.payload } }

        case DASHBOARD_TOP_CREATOR_LOADER: { return { ...state, top_creator_loader: action.payload } }
        case DASHBOARD_TOP_CREATOR_DATA: { return { ...state, top_creator: action.payload } }

        case DASHBOARD_TOP_PERFORMING_POST_LOADER: { return { ...state, top_performing_post_loader: action.payload } }
        case DASHBOARD_TOP_PERFORMING_POST_DATA: { return { ...state, top_performing_post: action.payload } }

        case DASHBOARD_TOP_PERFORMING_PRODUCT_LOADER: { return { ...state, top_performing_product_loader: action.payload } }
        case DASHBOARD_TOP_PERFORMING_PRODUCT_DATA: { return { ...state, top_performing_product: action.payload } }

        case DASHBOARD_CONTENT_GALLERY_LOADER: { return { ...state, content_gallery_loader: action.payload } }
        case DASHBOARD_CONTENT_GALLERY_DATA: { return { ...state, content_gallery: action.payload } }

        case DASHBOARD_WEBSITE_LOADER: { return { ...state, website_loader: action.payload } }
        case DASHBOARD_WEBSITE_DATA: { return { ...state, website: action.payload } }

        case DASHBOARD_SHOPON_LOADER: { return { ...state, shopon_loader: action.payload } }
        case DASHBOARD_SHOPON_DATA: { return { ...state, shopon: action.payload } }


        case GALLERY_DATA_UPDATE: {
            const { dashboarddata } = state;
            const { responseData, formData } = action.payload;
            const newGalleryData = updateGalleryWall(dashboarddata, responseData, formData);
            return { ...state, dashboarddata: newGalleryData, wallsLoader: false };
        }

        default:
            return { ...state }
    }

}

const updateGalleryWall = (dashboarddata, responseData, formData) => {
    const galleryData = { ...dashboarddata, data: [...dashboarddata.allWalls] };

    if (formData?.action === 1) { galleryData.allWalls.unshift(responseData); }

    if (formData?.action === 2) {
        galleryData.allWalls = galleryData.allWalls.map((item) => {
            if (item.id === formData.id) { return { ...item, name: formData.name, status: formData.status, autoUpdate: formData.autoUpdate, }; }
            return item; 
        });
    }

    if (formData?.action === 3) { galleryData.allWalls = galleryData.allWalls.filter((x) => x.id !== formData?.id); }

    return galleryData;
};