import { Counts_OverAll, MostActiveUsers_OverAll, Overview_OverAll, PopularChannelOverview_OverAll, ShoponRecordOverview_OverAll } from '../../utils/demoAnalyticsData'
import { UPDATE_DATE_FILTER, OVERVIEW_COUNTS, OVERVIEW_COUNTS_LOADER ,  MOST_ACTIVE_CREATORS_LOADER, MOST_ACTIVE_CREATORS, CONVERSION_OVERVIEW_LOADER, SHOPON_OVERVIEW_LOADER, WALL_OVERVIEW_LOADER, CONVERSION_OVERVIEW, SHOPON_OVERVIEW, WALL_OVERVIEW, POPULAR_CHANNEL, POPULAR_CHANNEL_LOADER } from '../keys'
var today = new Date();
const initialState = {
    counts: [
        { "label": "Total Posts", "tool_tip": "The accurate number of posts added to your Galleries.", "total": 0  },
        { "label": "Total Visitors", "tool_tip": "Number of people who visited your website.", "total": 0  },
        { "label": "Total Post Clicks", "tool_tip": "The number of clicks the Galleries posts received.", "total": 0  },
        { "label": "Total Assisted Revenue", "tool_tip": "Total revenue generated through shoppable posts.", "total": 0, "currency":'$' }
],
    counts_loader: true,

    most_active_users: [],
    most_active_users_loader: true,

    overview: {},
    overview_loader: false,

    shopon_overview: {},
    shopon_overview_loader: false,

    conversion_overview: [],
    conversion_overview_loader: true,

    popular_channel: [],
    popular_channel_loader: false,
    dateFilter: { startDate: new Date(new Date().setDate(today.getDate() - 30)), endDate:today },
}
export default function reducer(state = initialState, action) {
    switch (action.type) {
        case OVERVIEW_COUNTS: { return { ...state, counts: action.payload } }
        case OVERVIEW_COUNTS_LOADER: { return { ...state, counts_loader: action.payload } }

        case MOST_ACTIVE_CREATORS: { return { ...state, most_active_users: action.payload } }
        case MOST_ACTIVE_CREATORS_LOADER: { return {...state, most_active_users_loader: action.payload} }

        case WALL_OVERVIEW: { return { ...state, overview: action.payload } }
        case WALL_OVERVIEW_LOADER: { return {...state, overview_loader: action.payload} }

        case SHOPON_OVERVIEW: { return { ...state, shopon_overview: action.payload } }
        case SHOPON_OVERVIEW_LOADER: { return {...state, shopon_overview_loader: action.payload} }

        case CONVERSION_OVERVIEW: { return { ...state, conversion_overview: action.payload } }
        case CONVERSION_OVERVIEW_LOADER: { return {...state, conversion_overview_loader: action.payload} }

        case POPULAR_CHANNEL: { 
            return { ...state, popular_channel: action.payload } }
        case POPULAR_CHANNEL_LOADER: { return {...state, popular_channel_loader: action.payload} }

        case UPDATE_DATE_FILTER: { return { ...state, dateFilter: action.payload } }
        
        default:
            return { ...state }
    }

}