const cookies = new Cookies();

export const loginUser = (data, isRemember, rememberArr, redirectUrl, history, callback) => {
    return async (dispatch) => {
        localStorage.clear()
        await new HttpClient().post(LOGIN, data).then((response) => {
            const { responseData, response_code, response_message } = response.data;

            if (responseData && Object.keys(responseData).length > 0 && responseData.collaborator && Object.keys(responseData.collaborator).length > 0 && responseData.collaborator?.activeAccount != 0){
                dispatch(checkCollaborator(responseData, history, true))
                if(!localStorage.getItem('isReview')){
                    localStorage.setItem('isReview',true)
                }
            }

            else if (responseData && Object.keys(responseData).length > 0) {

                if(!localStorage.getItem('isReview')){
                    localStorage.setItem('isReview',true)
                }

                if (!JSON.parse(localStorage.getItem('isAdmin')) && (responseData && responseData.Intercom && Object.keys(responseData.Intercom).length > 0)) {
                    window.intercomSettings = responseData.Intercom;
                    window.Intercom('boot', responseData.Intercom);
                }
                if (responseData.access) {
                    if (isRemember) {
                        cookies.set("__RememberDetails", rememberArr)
                    } else {
                        cookies.remove("__RememberDetails", rememberArr)
                    }
                }
                SET_COOKIES("__TagshopLogin", 1, 30, 'tagshop.ai')
                localStorage.setItem('__TagshopLogin', 1)
                if (responseData.access == 2) {
                    const { user } = responseData;
                    localStorage.setItem('steps', 1);
                    localStorage.setItem('emailId', responseData.user.emailId);
                    localStorage.setItem('token', responseData.token)
                    if (user && Object.keys(user).length > 0) {
                        localStorage.setItem('ownerId', user.userhashId)
                    }
                    history("/accounts/verify")
                }

                if (responseData.access == 3) {
                    localStorage.setItem('steps', 1);
                    localStorage.setItem('emailId', responseData.user.emailId);
                    localStorage.setItem('token', responseData.token)
                    history("/accounts/price");
                }

                else {

                    const { user, UserRule } = responseData;
                    if (UserRule && UserRule.walls) {
                        localStorage.setItem('token', responseData.token);
                        dispatch({ type: USER_TOKEN, payload: responseData.token });
                        dispatch({ type: USER_AUTHENTICATED_LOGIN, payload: { ...responseData, countryCode: data && data.country ? data.country : 'US' } });

                        if (user?.plan_exceed == 2) {
                            const { user } = responseData;
                            localStorage.setItem('wallLimitExceed', true);
                            localStorage.setItem('token', responseData.token);
                            localStorage.setItem('ownerId', user.userhashId)
                            dispatch(TAGSHOP_USER_HOME_DATA())
                            history('/wall/extrawallfeeds')

                        }
                        if (user?.restriction_exceed == 1) {
                            const { user } = responseData;
                            dispatch({ type: PLAN_LIMIT_EXCEED, payload: true, gallery_views_limit: response_message?.gallery_views_limit })
                            localStorage.setItem('token', responseData.token);
                            localStorage.setItem('ownerId', user.userhashId)
                            dispatch(TAGSHOP_USER_HOME_DATA())
                        }
                        if (user && Object.keys(user).length > 0) {

                            localStorage.setItem('ownerId', user.userhashId)

                            dispatch(TAGSHOP_USER_HOME_DATA());

                        }
                        if (responseData.UserPlan.taggshopAccess == 0) {
                            history("/product/switch/taggshop")
                        }
                        else if (!(responseData.UserPlan.planId.split(",").some(id => ['38', '39', '56', '66', '67', '57', '1'].includes(id.trim())))) {
                            history("/accounts/expire")
                        }
                        else {
                            history("/home")
                        }
                    }


                }
            }
            else{
                callback(response_message)
                TOAST_ERROR(response_message)
            } 
        }).catch((ex) => {
            const { data } = ex.response;
            
            callback(data?.responseMessage || data?.message || "Something went wrong, please try again later.")
        })
    }
}

