export const getIPDetails = () => {
    const timeoutPromise = new Promise((resolve, reject) => {
        setTimeout(() => {
            reject(new Error('Request timed out'));
        }, 2000);
    });

    const ipInfoPromise = new HttpClient().get(IP_INFO, { validateStatus: false })
        .then(ipResponse => {
            const { data } = ipResponse;
            return data;
        })
        .catch(error => {
            return '';
        });

    return Promise.race([timeoutPromise, ipInfoPromise]);
};

const getCookies = (key) => {
    const cookies = document.cookie;
    const cookieArray = cookies.split(';');
    const cookieObject = {};
    cookieArray.forEach(cookie => {
        const [cookieKey, cookieValue] = cookie.split('=');
        cookieObject[cookieKey.trim()] = cookieValue.trim();
    });
    return cookieObject[key];
}

