export const loginWithShopify = (searchParams, history) => {

    const script = document.createElement('script');
    script.type = 'text/javascript';
    script.innerHTML = `
        (function() {
            var AppBridge = window['app-bridge'];
            var createApp = AppBridge.createApp;
            var actions = AppBridge.actions;
            var Toast = actions.Toast;
            var Redirect = actions.Redirect;

            var app = createApp({ apiKey: '${shopifyApiKey}', host: '${searchParams.host}' });

            // Get session token and refresh it every 30 seconds
            var appbridge_session_token;
            window['app-bridge-utils'].getSessionToken(app).then(token => {
                appbridge_session_token = token;
            });
            setInterval(function () {
                window['app-bridge-utils'].getSessionToken(app).then(token => {
                    appbridge_session_token = token;
                });
            }, 30000);
        })();
    `;

    document.head.appendChild(script);


    return async (dispatch) => {
        await new HttpClient().post(SHOPIFY_LOGIN, searchParams).then((response) => {
            const { responseData, responseCode, response_message } = response.data;

            if (responseData && Object.keys(responseData).length > 0) {
                localStorage.setItem('token', responseData.token);
                
                localStorage.setItem('isReview',true)
                

                var currentTimestamp = Math.floor(Date.now() / 1000);
                const planId = responseData.UserPlan.planId && responseData.UserPlan.planId.split(',')

                if (!JSON.parse(localStorage.getItem('isAdmin')) && (responseData && responseData.Intercom && Object.keys(responseData.Intercom).length > 0)) {
                    window.intercomSettings = responseData.Intercom;
                    window.Intercom('boot', responseData.Intercom);
                }

                if (responseData && responseData.user && responseData.user.extra_data) {
                    var extraData = JSON.parse(responseData.user.extra_data)
                    if (extraData && !extraData?.wall_created && extraData?.db_table) {
                        localStorage.removeItem('wallId');
                        localStorage.removeItem('shopifyLogin');
                        localStorage.removeItem('steps');
                    }
                }

                if (responseData.user.access == 3) {
                    localStorage.setItem('steps', 1);
                    localStorage.setItem('shopifyLogin', 1)
                    localStorage.setItem('emailId', responseData.user.emailId);
                    localStorage.setItem('token', responseData.token)
                    localStorage.setItem('shopId', responseData?.shopifyShopDetails?.shopId)
                    dispatch({ type: USER_TOKEN, payload: responseData.token });
                    dispatch({ type: USER_AUTHENTICATED_LOGIN, payload: { ...responseData, countryCode: 'US' } });
                    if (responseData?.shopifyShopDetails?.shopId) SHOPIFY_PRODUCT_SYNC(responseData?.shopifyShopDetails?.shopId, history("/accounts/price"))
                    else history("/accounts/price")
                }



                else {
                    const { user, UserRule } = responseData;
                    if (UserRule && UserRule.walls) {
                        localStorage.removeItem('steps', 1);
                        localStorage.setItem('token', responseData.token);
                        localStorage.setItem('shopifyLogin', 1)
                        dispatch({ type: USER_TOKEN, payload: responseData.token });
                        dispatch({ type: USER_AUTHENTICATED_LOGIN, payload: { ...responseData, countryCode: 'US' } });

                        if (responseData?.user?.plan_exceed == 2) {
                            const { user } = responseData;
                            localStorage.setItem('token', responseData.token);
                            localStorage.setItem('wallLimitExceed', true);
                            localStorage.setItem('ownerId', user.userhashId)
                            dispatch(TAGSHOP_USER_HOME_DATA())
                            if (!(window.location.pathname.includes("/price/failed") || window.location.pathname.includes("/price/success") || window.location.pathname.includes("/shopify/success") || window.location.pathname.includes("/paymentPaidCallback"))) history('/wall/extrawallfeeds')
                        }
                        else {
                            dispatch({ type: PLAN_LIMIT_EXCEED, payload: false })
                            localStorage.setItem('wallLimitExceed', false)
                        }
                        if (responseData?.user?.restriction_exceed == 1) {
                            const { user } = responseData;
                            dispatch({ type: PLAN_LIMIT_EXCEED, payload: true, gallery_views_limit: response_message?.gallery_views_limit })

                            localStorage.setItem('ownerId', user.userhashId)
                            dispatch(TAGSHOP_USER_HOME_DATA())
                        }
                        if (user && Object.keys(user).length > 0) {
                            if (!(responseData.UserPlan.planId && responseData.UserPlan.planId.split(",").some(id => ['38', '39', '56', '66', '67', '57', '1'].includes(id.trim())))) {
                                history("/accounts/expire")
                            }

                            if (responseData.UserPlan.expiresAt != 0 && currentTimestamp > responseData.UserPlan.expiresAt && planId && planId.length == 1 && ['44', '14', '1'].includes(planId)) {
                                localStorage.setItem('accountExpire', true)
                                history("/accounts/expire")
                            }

                            localStorage.setItem('ownerId', user.userhashId)

                            dispatch(TAGSHOP_USER_HOME_DATA());

                        }
                        if (responseData.UserPlan.taggshopAccess == 0) {
                            history("/product/switch/taggshop")
                        }
                        else if (!(responseData.UserPlan.planId.split(",").some(id => ['38', '39', '56', '66', '67', '57', '1'].includes(id.trim())))) {
                            history("/accounts/expire")
                        }
                        else {
                            if (responseData?.shopifyShopDetails?.shopId) SHOPIFY_PRODUCT_SYNC(responseData?.shopifyShopDetails?.shopId, () => history("/home"))
                            else history("/home")
                        }
                    }
                }
            }

        }).catch((ex) => {
            TOAST_ERROR('Somthing went worng!')
        })

    }

}


