export const loginWithBigcommerce = (obj, history) => {
    new HttpClient().post(BIGCOMMERCE_OAUTH, obj).then(res => {
        const { responseData } = res.data.responseData
        if (responseData.token) {
            localStorage.setItem('token', responseData.token)
            localStorage.setItem('bigcommerceLogin', 1)
            store.dispatch(getUserInfo_afterChanges())

            if (responseData.emailStatus == 0) {
                if (responseData.access == 3) {
                    localStorage.setItem('steps', 1);
                    localStorage.setItem('emailId', responseData.user.emailId);
                    localStorage.setItem('token', responseData.token)
                    localStorage.setItem('shopId', responseData.shopId)
                    if (responseData.shopId) {
                        SYNC_BIGCOMMERCE_PRODUCTS(responseData.shopId, history("/accounts/price"))
                    }
                    else history("/accounts/price")
                } else {
                    if (responseData.shopId) {
                        SYNC_BIGCOMMERCE_PRODUCTS(responseData.shopId, () => { window.location.href = `${HOST_URL}init/index/bigcommerce` })
                    }
                    else {
                        window.location = `${HOST_URL}init/index/bigcommerce`
                    }
                }
            }
            else {
                if (responseData.access == 3) {
                    localStorage.setItem('steps', 1);
                    localStorage.setItem('emailId', responseData.user.emailId);
                    localStorage.setItem('token', responseData.token)
                    localStorage.setItem('shopId', responseData.shopId)
                    if (responseData.shopId) {
                        SYNC_BIGCOMMERCE_PRODUCTS(responseData.shopId, history("/accounts/price"))
                    }
                    else history("/accounts/price")
                }
                else {
                    if (responseData.shopId) {
                        SYNC_BIGCOMMERCE_PRODUCTS(responseData.shopId, () => { window.location.href = `${HOST_URL}home` })
                    }
                    else {
                        window.location = `${HOST_URL}home`
                    }
                }
            }
        }
    })
}

