import { DISPATCH_SHOPIFY_CALL, DISPATCH_STRIPE_CALL } from "./keys";
const initialState = { callApi:[] ,shopify:[]}
export default function reducer(state = initialState, action) {
    switch (action.type) {
        case DISPATCH_STRIPE_CALL: {
            return { ...state, callApi: action.payload }
        }
        case DISPATCH_SHOPIFY_CALL: {
            return { ...state, shopify: action.payload }
        }
          default:
            return { ...state }
    }

}