import { MODERATION_GET_SAVE_TAGS, MODERATION_ADD_SAVE_TAGS, MODERATION_REMOVE_SAVE_TAGS } from "./keys";
const initialState={
    selectedTags:[]
}

export default function  reducer(state=initialState, action){
    switch(action.type){
        case MODERATION_GET_SAVE_TAGS: 
          const data1 = action.payload && action.payload.length > 0 ? action.payload.split(','):''
            return{...state, selectedTags:data1}
        case MODERATION_ADD_SAVE_TAGS: 
            return{...state, selectedTags:[...state.selectedTags, action.payload]}
        case MODERATION_REMOVE_SAVE_TAGS: 
            const data = state.selectedTags.filter((item)=> action.payload != item ) 
            return{...state, selectedTags:data}                
        default:
            return{...state}
    }
}

