export const clickToPostStatus = (index, postId, status) => {
    const { listData } = store.getState().moderation
    return (dispatch) => {
        new HttpClient().post(`${MODERATION_POST_STATUS}`, { wallId: localStorage.getItem('wallId'), postId: String(postId), status: status, })
            .then((response) => {
                const { responseCode, responseMessage, responseStatus } = response.data;
                if (responseCode === 200) {
                    const updateData = listData?.map((item, iIndex) => iIndex === index ? { ...item, status } : item);
                    status === 1 ? toast.success('Post is Public now') : toast.error('Post is Private now');
                    dispatch({ type: MODERATION_POST_STATUS_UPDATE, payload: updateData });
                    dispatch(TAGSHOP_USER_HOME_DATA())
                    setTimeout(() => dispatch(getModeration()), 100)
                }
            })
    }
}


export const clickToPostStatusALL = (status) => {
    return (dispatch) => {
        Alert.alertFire({
            title: 'Are you sure?',
            text: `You want to ${status === 1 ? '' : 'dis'}approve selected post?`,
            icon: "warning",
            showCancelButton: true,
            confirmButtonColor: "#5354fc",
            confirmButtonText: "Continue"
        }).then((result) => {
            if (!result.value) return;

            const { listData, check_uncheck_all, details } = store.getState().moderation;
            const postId = check_uncheck_all?.data?.map(item => item.postId) || [];
            const { NMprivatePost, NMPublicPost } = check_uncheck_all?.data?.reduce((acc, item) => {
                acc[item.status === 2 ? 'NMprivatePost' : 'NMPublicPost'] += 1;
                return acc;
            }, { NMprivatePost: 0, NMPublicPost: 0 }) || { NMprivatePost: 0, NMPublicPost: 0 };

            new HttpClient().post(MODERATION_POST_STATUS, { wallId: localStorage.getItem('wallId'), postId: postId.join(), status })
                .then(({ data: { responseCode, responseMessage } }) => {
                    if (responseCode === 200) {
                        const updateData = listData.map(item => ({ ...item, status: item.isChecked ? status : item.status }));

                        dispatch(UPDATE_USER_HOME_DATA());
                        dispatch({ type: MODERATION_CHECKED_DATA_REMOVE_ALL });

                        const updateDetailsData = {
                            ...details,
                            privatepost: parseInt(details.privatepost) + (status === 1 ? -NMprivatePost : NMPublicPost),
                            publicpost: parseInt(details.publicpost) + (status === 1 ? NMprivatePost : -NMPublicPost)
                        };

                        dispatch({ type: MODERATION_GET_DETAILS, payload: updateDetailsData });
                        toast[status === 1 ? 'success' : 'error'](`Selected posts are ${status === 1 ? 'public' : 'private'} now.`);
                        dispatch({ type: MODERATION_POST_STATUS_UPDATE, payload: updateData });
                        setTimeout(() => dispatch(getModeration()), 400);
                    } else {
                        toast.error(responseMessage);
                    }
                });
        });
    };
};


export const clickToPostDeleteALL = (navigate) => {
    return (dispatch) => {
        Alert.alertFire({
            title: 'Are you sure?',
            text: 'You want to delete selected post?',
            icon: "warning",
            showCancelButton: true,
            confirmButtonColor: "#5354fc",
            confirmButtonText: "Continue"
        }).then((result) => {
            if (!result.value) return;

            const { listData, check_uncheck_all } = store.getState().moderation;
            const { extraPosts, extraProducts } = store.getState().limitExceed;
            const postId = check_uncheck_all?.data?.map(item => item.postId) || [];
            //const prodId = check_uncheck_all?.data?.map(item => item.postProduct.id) || []
            const prodId = check_uncheck_all?.data?.flatMap(item => item.postproduct.map(product => product.id)) || [];

            const products = check_uncheck_all?.data?.reduce((sum, item) => sum + item.postproduct.length, 0)

            new HttpClient().post(MODERATION_POST_DELETE, { wallId: localStorage.getItem('wallId'), postId: postId.join(), uppId: prodId.join() })
                .then(({ data: { responseCode, responseMessage } }) => {
                    if (responseCode === 200) {
                        dispatch(UPDATE_USER_HOME_DATA());
                        dispatch({ type: MODERATION_CHECKED_DATA_REMOVE_ALL });
                        if(localStorage.getItem('wallLimitExceed') == 'true') dispatch({type:DELETE_EXTRA_LIMITS, payload:{posts:extraPosts > 0 ? postId.length : 0, products:extraProducts > 0 ? products : 0, navigate:navigate}})
                        toast.error('Selected posts are deleted now');
                        dispatch({ type: MODERATION_POST_STATUS_UPDATE, payload: listData });
                        setTimeout(() => dispatch(getModeration()), 400);
                    } else {
                        toast.error(responseMessage);
                    }
                }).catch((error) => {
                    const errorMessage = error.response?.data?.responseMessage || 'An error occurred. Please try again later.';
                    toast.error(errorMessage);
                });
        });
    };
};


