export const selectPostUpdate = (index, callBack) => {
    return (dispatch) => {
        const { listData, isCheckedPostCount } = store.getState().moderation;

        if (listData?.[index]) {
            listData[index].isChecked = !listData[index].isChecked;

            const checkedCount = listData.filter(item => item.isChecked).length;
            const status = checkedCount === listData.length;

            const actionType = listData[index].isChecked ? MODERATION_CHECKED_DATA : MODERATION_CHECKED_DATA_REMOVE;
            dispatch({ type: actionType, payload: { status, data: listData[index] } });
            dispatch({ type: MODERATION_UPDATE_CHECK_ALL, payload: { listData, isCheckedPostCount } });

            setTimeout(() => callBack?.(), 100);
        }
    }
};


export const clickToPostPin = (index, postId, status) => {
    return (dispatch) => {
        const { listData } = store.getState().moderation;

        new HttpClient().post(`${MODERATION_POST_PIN}`, { wallId: localStorage.getItem('wallId'), postId: postId, status: status ? 0 : 1, })
            .then(({ data: { responseCode, responseData } }) => {
                if (responseCode === 200) {
                    const updateData = listData.map((item, iIndex) =>
                        iIndex === index ? { ...item, pin: status ? 0 : responseData?.indexing } : item
                    );


                    updateData.sort((a, b) => {
                        if (a.pin === b.pin) return 0;
                        if (a.pin === 1 || b.pin === 0) return -1;
                        return 1;
                    });

                    dispatch({ type: MODERATION_PIN_UPDATE_STATUS, payload: updateData });
                    status ? toast.error('Post Removed from top') : toast.success('Post is pinned to top');
                }
            })
            .catch((error) => {
                console.error(error);
            });
    };
};


export const clickToDeletePost = (item, index, navigate) => {
    return (dispatch) => {
        Alert.alertFire({
            title: "Are you sure?",
            text: "You will not be able to recover this post.",
            icon: "warning",
            showCancelButton: true,
            confirmButtonColor: "#5354fc",
            confirmButtonText: "Yes, delete it!",
            closeOnConfirm: false
        }).then((result) => {
            if (!result.value) return;

            const { listData } = store.getState().moderation;
            const { extraPosts, extraProducts } = store.getState().limitExceed;
            const prodId = item.postproduct.length > 0 ? item.postproduct.map(prod => prod.id) : []

            new HttpClient().post(MODERATION_POST_DELETE, { postId: item.postId, wallId: localStorage.getItem('wallId'), uppId:prodId.join() })
                .then(({ data: { responseCode, responseMessage } }) => {
                    if (responseCode === 200) {
                        dispatch(UPDATE_USER_HOME_DATA());
                        if(localStorage.getItem('wallLimitExceed') == 'true') dispatch({type:DELETE_EXTRA_LIMITS, payload:{posts:extraPosts > 0 ? 1 : 0, products:extraProducts > 0 ? item.postproduct?.length : 0, navigate:navigate}})

                        if (listData?.length > 0 && listData[index]) {
                            const deletedPost = listData[index];
                            deletedPost.isChecked = false;

                            const checkedItems = listData.filter(item => item.isChecked);
                            const allChecked = checkedItems.length === listData.length;

                            dispatch({ type: MODERATION_CHECKED_DATA_REMOVE, payload: { status: allChecked, data: deletedPost } });
                            listData.splice(index, 1);
                            dispatch({ type: MODERATION_PIN_UPDATE_STATUS, payload: listData });
                        }

                        toast.success('Your post has been deleted.');
                        dispatch(getModeration());
                    } else {
                        toast.error(responseMessage);
                    }
                })
                .catch((error) => {
                    console.error('Error deleting post:', error);
                    toast.error('An error occurred while deleting the post. Please try again later.');
                });
        });
    };
};


