export const CREATE_FEED = (data, callBack, isReactNav, closeModal) => {
    try {
        new HttpClient().post(CREATE_FEED_TWITTER, data, { validateStatus: false }).then(res => {

            const { responseCode, resposneMessage, response, postCount, response_code } = res.data
            localStorage.setItem('selectedNetwork', null)

            if (responseCode == 200 || response_code == 200) {
                TOAST_SUCCESS(resposneMessage)
                if (postCount != null && data.filter != 62) {
                    TOAST_SUCCESS(`${postCount} post added successfully`)
                    setTimeout(() => {
                        window.location.replace(`${HOST_URL}content/moderation/${localStorage.getItem('wallId')}`)
                    }, 1000);
                }

                if (data.filter != 62 && response && response.length) {
                    GET_POST_COUNT(response[0], data.networkId, closeModal, isReactNav, callBack)
                }
                if (data.filter == 62 && postCount && postCount.length) {
                    GET_POST_COUNT(postCount[0], data.networkId, closeModal, isReactNav, callBack)
                }
            }
            else {
                TOAST_ERROR(resposneMessage.message ? resposneMessage.message : resposneMessage)
                setTimeout(() => {
                    callBack(`/content/moderation/${localStorage.getItem('wallId') ? localStorage.getItem('wallId') : ''}`)
                    store.dispatch(toggleAddFeedsSection(false))

                }, 2000);
            }
        }).catch(err => {
            TOAST_ERROR("Some Error Occured!!")
            localStorage.setItem('selectedNetwork', null)
            if (isReactNav) {
                setTimeout(() => {
                    callBack(`/content/moderation/${localStorage.getItem('wallId') ? localStorage.getItem('wallId') : ''}`)
                    store.dispatch(toggleAddFeedsSection(false))

                }, 700);
            }
            else window.location.replace(`${HOST_URL}content/moderation/${localStorage.getItem('wallId')}`)
        })
    } catch (error) {
        console.log(error)
    }
}

