export const ExpiredPostInstaQueue = (item) => {
    const { userData } = store.getState().authorized;
    if (!ExpiredPostQueue.includes(item) && userData && PaidPlanIds.includes(userData?.user_data?.UserPlan?.planId) && userData?.user_data?.user?.is_trial == 0) {
        ExpiredPostQueue.push(item)
    }
    if (ExpiredPostQueue.length == 1) processImageInQueue()
}

const processImageInQueue = async () => {
    try {
        const { dispatch } = store
        const { userData } = store.getState().authorized;
        if (ExpiredPostQueue?.length > 0 && Object.keys(ExpiredPostQueue[0]).length > 0) {
            const item = ExpiredPostQueue[0]
            const { feedId, spostId, link, postParent, parentLink, status } = item
            const type = link?.includes("reel") ? 3 : 2
            const refreshPostId = document.querySelector(`.refresh_post_media_${item.id}`);
            refreshPostId?.setAttribute('style', 'display:none !important')
            const payload = { feedId, postId: spostId, postParent: postParent, wallId: localStorage.getItem("wallId"), link: parentLink ? parentLink : link, db_table: userData?.user_data?.UserPlan?.db_table, owner: localStorage.getItem('ownerId') }
            if (status == 1) {
                INSTA_AGENT_UPDATE({ ...payload }).then((res) => {
                    const { response_code, responseData } = res.data
                    if (response_code == 200 && responseData?.length) {
                        dispatch(UPDATE_LISTDATA_BY_ID(responseData, type))
                        ExpiredPostQueue.shift();
                        processImageInQueue()
                    }
                    else {
                        ExpiredPostQueue.shift();
                        processImageInQueue()
                        refreshPostId?.setAttribute('style', 'display:block !important')
                    }
                }).catch(error => {
                    const { resposne_message } = error.response.data
                    ExpiredPostQueue.shift();
                    processImageInQueue()
                    refreshPostId?.setAttribute('style', 'display:block !important')
                })
            }
            else {
                ExpiredPostQueue.shift();
                processImageInQueue()
                refreshPostId?.setAttribute('style', 'display:block !important')
            }
        }
    }
    catch (error) {
        console.log("error", error)
    }
}


export const UPDATE_INSTA_POST_ACTION = (item) => (dispatch) => {
    const { userData } = store.getState().authorized;
    const { feedId, postId, link, postParent, parentLink } = item
    const type = link && link.includes("reel") ? 3 : 2
    const refreshPostId = document.querySelector(`.refresh_post_media_${item.id}`);
    const refreshIcon = document.querySelector(`.refresh-icon-${item.id}`);
    refreshIcon?.setAttribute('style', 'animation:animation-spinner 1.5s linear infinite');
    refreshPostId?.setAttribute('style', 'pointer-events:none');
    const toastId = TOAST_LOADING()
    const payload = { feedId, postId: postId, postParent: postParent, wallId: localStorage.getItem("wallId"), link: parentLink ? parentLink : link, db_table: userData?.user_data?.UserPlan?.db_table, owner: localStorage.getItem('ownerId') }
    INSTA_AGENT_UPDATE({ ...payload }).then((res) => {
        const { response_code, responseData } = res.data
        if (response_code == 200 && responseData && responseData.length) {
            dispatch(UPDATE_LISTDATA_BY_ID(responseData, type))
            TOAST_UPDATE(toastId, "success", "Post Updated Successfully")
            refreshPostId?.setAttribute('style', 'display:none');
            refreshIcon?.setAttribute('style', 'animation:none');
        }
        else {
            TOAST_UPDATE(toastId, "error", "Error finding Post!")
            refreshPostId?.setAttribute('style', 'display:block');
            refreshIcon?.setAttribute('style', 'animation:none');
        }
    }).catch(error => {
        const { resposne_message } = error.response.data
        TOAST_UPDATE(toastId, "error", resposne_message || "Something went wrong!")
        refreshPostId?.setAttribute('style', 'display:block');
        refreshIcon?.setAttribute('style', 'animation:none');
    })
}


