import { MANAGEFEEDS_GET_DATA, DISPATCH_FEED_STATUS, DISPATCH_DELETE_FEED, DISPATCH_UPDATE_ACCOUNT, UPDATE_FEED_LOADER } from "../reducer/keys"
import { FACEBOOK_AUTOCOMPLETE, GET_MANAGEFEEDS, HANDLE_AUTOCOMPLETE, FEED_STATUS_UPDATE, DELETE_FEED, UPDATE_SOCIAL_ACCOUNT } from "./api"
import HttpClient from "./http-client"
import { TOAST_LOADING, TOAST_SUCCESS, TOAST_DISMISS, capitalizeFirstLetter, TOAST_ERROR, TOAST_UPDATE } from "../utils"
import { UPDATE_USER_HOME_DATA } from "./sceneActions"
import { GET_ALL_WEBSITE_LIST } from "./websiteAction"


export const GET_FEEDS = () => {
    return (dispatch) => {
        try {
            if (localStorage.getItem('wallId')) {
                dispatch({ type: UPDATE_FEED_LOADER, payload: true })
                new HttpClient().get(`${GET_MANAGEFEEDS}/${parseInt(localStorage.getItem('wallId'))}`).then(res => {
                    const { responsedata, responseCode, message } = res.data
                    if (responseCode == 200) dispatch({ type: MANAGEFEEDS_GET_DATA, payload: { "feeds": responsedata.feeds, "total": responsedata.totalFeed, } })
                    else console.error("Someting went wrong! ", message)
                }).catch(error => {
                    console.error('error', error)
                })
            }
            else dispatch({ type: UPDATE_FEED_LOADER, payload: false })
        }
        catch (error) {
            console.error('error', error)
        }

    }
}

export const ACTION_UPDATE_SOCIAL_ACCOUNT = (accountId, feedId, callback) => {

    const toastId = TOAST_LOADING();
    return (dispatch) => {
        new HttpClient().post(UPDATE_SOCIAL_ACCOUNT, { feedId: feedId, connectedAccountId: accountId }).then(res => {
            const { data } = res
            if (data.responseCode == 200) {
                dispatch({ type: DISPATCH_UPDATE_ACCOUNT, payload: { "feedId": feedId, "accountId": accountId, } })
                TOAST_UPDATE(toastId, "success", `Account updated successfully`)
                callback('account');
            } else TOAST_DISMISS(toastId)
        }).catch((error) => {
            console.log("ERROR", error)
            TOAST_UPDATE(toastId, "error", `Something went wrong!`)
        })
    }
}
export const ACTION_DELETE_FEED = (feedId, networkId, callback) => {
    try {
        const toastId = TOAST_LOADING();
        return (dispatch) => {
            new HttpClient().delete(DELETE_FEED, { data: { wallId: localStorage.getItem('wallId'), feedId: [`${feedId}`], networkId: [`${networkId}`] } }).then(res => {
                const { data } = res
                if (data.responseCode == 200) {
                    TOAST_UPDATE(toastId, "success", data.responseMessage)
                    var callBackFunction = callback;
                    setTimeout(() => {
                        dispatch(UPDATE_USER_HOME_DATA());
                        if (networkId == 29) dispatch(GET_ALL_WEBSITE_LIST())
                        dispatch({ type: DISPATCH_DELETE_FEED, payload: feedId })
                        if (callBackFunction) callBackFunction();
                    }, 3000)

                }
                else TOAST_DISMISS(toastId)
            }).catch((error) => {
                if (error?.response?.data?.responseMessage) TOAST_UPDATE(toastId, "error", error?.response?.data?.responseMessage)
                else TOAST_DISMISS(toastId)
            })
        }
    }
    catch (error) {
        console.log("ERROR", error)
    }
}
export const ACTION_FEED_STATUS = (feedId, status, action, callback) => dispatch => {
    const data = { feedId, action, status, wallId: localStorage.getItem('wallId') };
    new HttpClient().post(FEED_STATUS_UPDATE, data)
        .then(({ data }) => {
            if (data.responseCode == 200) {
                dispatch(UPDATE_USER_HOME_DATA());
                dispatch({ type: DISPATCH_FEED_STATUS, payload: { feedId, status, action } });
                TOAST_SUCCESS(`${capitalizeFirstLetter(action)} Updated Successfully.`);
                callback();
            }
            else {
                TOAST_ERROR(data.responseMessage);
            }
        })
        .catch(error => console.log("ERROR", error));
};
export const AUTOCOMPLETE = (data) => {
    const url = data.networkId == 1 ? HANDLE_AUTOCOMPLETE : FACEBOOK_AUTOCOMPLETE
    return new HttpClient().post(url, data)
}